class ResponseCache:
    def __init__(self, max_size: int = 1000, ttl: int = 3600):
        self.max_size = max_size
        self.ttl = ttl
        self._cache: Dict[str, Tuple[Any, datetime]] = {}
        self._access_times: Dict[str, datetime] = {}

    def _generate_key(self, messages: List[Dict], tools: Optional[List[Dict]], params: Dict) -> str:
        content = json.dumps({
            "messages": messages,
            "tools": tools or [],
            "params": {k: v for k, v in params.items() if k not in ["stream", "n"]}
        }, sort_keys=True)
        return hashlib.sha256(content.encode()).hexdigest()

    def get(self, messages: List[Dict], tools: Optional[List[Dict]], params: Dict) -> Optional[Any]:
        key = self._generate_key(messages, tools, params)
        if key in self._cache:
            value, timestamp = self._cache[key]
            if datetime.now() - timestamp < timedelta(seconds=self.ttl):
                self._access_times[key] = datetime.now()
                return value
            else:
                del self._cache[key]
                if key in self._access_times:
                    del self._access_times[key]
        return None

    def set(self, messages: List[Dict], tools: Optional[List[Dict]], params: Dict, value: Any) -> None:
        key = self._generate_key(messages, tools, params)

        if len(self._cache) >= self.max_size:
            self._evict_lru()

        self._cache[key] = (value, datetime.now())
        self._access_times[key] = datetime.now()

    def _evict_lru(self) -> None:
        if not self._access_times:
            return
        oldest_key = min(self._access_times.keys(), key=lambda k: self._access_times[k])
        del self._cache[oldest_key]
        del self._access_times[oldest_key]

class RateLimiter:
    def __init__(self, rpm: int = 60, tpm: int = 1000000):
        self.rpm = rpm
        self.tpm = tpm
        self.requests = []
        self.tokens = []

    async def acquire(self, tokens: int = 0) -> None:
        now = datetime.now()

        minute_ago = now - timedelta(minutes=1)
        self.requests = [req_time for req_time in self.requests if req_time > minute_ago]
        self.tokens = [(token_count, token_time) for token_count, token_time in self.tokens if token_time > minute_ago]

        if len(self.requests) >= self.rpm:
            sleep_time = 60.0 - (now - self.requests[0]).total_seconds()
            if sleep_time > 0:
                await asyncio.sleep(sleep_time)

        total_tokens = sum(count for count, _ in self.tokens)
        if total_tokens + tokens > self.tpm:
            sleep_time = 60.0 - (now - self.tokens[0][1]).total_seconds()
            if sleep_time > 0:
                await asyncio.sleep(sleep_time)

        self.requests.append(now)
        self.tokens.append((tokens, now))

def apply_ultimate_warning_suppression() -> None:
    os.environ["PYTHONWARNINGS"] = "ignore"
    os.environ["GOOGLE_GENAI_SUPPRESS_WARNINGS"] = "1"
    os.environ["GRPC_VERBOSITY"] = "ERROR"
    os.environ["GLOG_MINLOGLEVEL"] = "3"
    os.environ["TF_CPP_MIN_LOG_LEVEL"] = "3"

    warnings.warn = _silent_warn
    warnings.showwarning = _silent_showwarning
    warnings.formatwarning = _silent_formatwarning

    gemini_warning_patterns = [
        ".*non-text parts in the response.*",
        ".*function_call.*",
        ".*returning concatenated text result.*",
        ".*check out the non text parts.*",
        ".*text parts.*",
        ".*response.*function_call.*",
        ".*non text parts for full response.*",
        ".*candidates.*",
        ".*finish_reason.*",
        ".*genai.*",
        ".*google.*",
        ".*generativeai.*",
        ".*google.genai.*",
        ".*google.generativeai.*",
        ".*grpc.*",
        ".*http.*",
        ".*ssl.*",
        ".*certificate.*",
        ".*urllib3.*",
        ".*httpx.*",
        ".*asyncio.*",
    ]

    warning_categories = [
        UserWarning,
        Warning,
        FutureWarning,
        DeprecationWarning,
        RuntimeWarning,
        PendingDeprecationWarning,
        ImportWarning,
        UnicodeWarning,
        BytesWarning,
        ResourceWarning,
    ]

    for pattern in gemini_warning_patterns:
        for category in warning_categories:
            warnings.filterwarnings("ignore", message=pattern, category=category)
        warnings.filterwarnings("ignore", message=pattern)

    google_modules = [
        "google",
        "google.genai",
        "google.generativeai",
        "google.ai",
        "google.cloud",
        "google.protobuf",
        "grpc",
        "googleapis",
        "google.auth",
        "google.api_core",
        "google.api",
        "googleapiclient",
    ]

    for module in google_modules:
        for category in warning_categories:
            warnings.filterwarnings("ignore", category=category, module=module)
        warnings.filterwarnings("ignore", module=module)

    google_loggers = [
        "google",
        "google.genai",
        "google.generativeai",
        "google.ai.generativelanguage",
        "google.ai",
        "google.cloud",
        "grpc",
        "grpc._channel",
        "urllib3",
        "httpx",
        "asyncio",
        "google.auth",
        "google.api_core",
        "googleapiclient",
    ]

    for logger_name in google_loggers:
        logger = logging.getLogger(logger_name)
        logger.setLevel(logging.CRITICAL + 1)
        logger.propagate = False
        logger.disabled = True
        logger.handlers.clear()

        for child_logger in [
            log_name
            for log_name in logging.Logger.manager.loggerDict
            if log_name.startswith(logger_name + ".")
        ]:
            child = logging.getLogger(child_logger)
            child.setLevel(logging.CRITICAL + 1)
            child.propagate = False
            child.disabled = True
            child.handlers.clear()

    warnings.simplefilter("ignore")
    for category in warning_categories:
        warnings.simplefilter("ignore", category)

class UltimateSuppression:
    def __init__(self):
        self.original_stderr = None
        self.original_stdout = None
        self.original_warn = None
        self.original_showwarning = None
        self.original_formatwarning = None
        self.devnull = None
        self.original_filters = None

    def __enter__(self):
        self.original_stderr = sys.stderr
        self.original_stdout = sys.stdout
        self.original_warn = warnings.warn
        self.original_showwarning = warnings.showwarning
        self.original_formatwarning = warnings.formatwarning
        self.original_filters = warnings.filters[:]

        self.devnull = open(os.devnull, "w")
        sys.stderr = self.devnull

        warnings.warn = _silent_warn
        warnings.showwarning = _silent_showwarning
        warnings.formatwarning = _silent_formatwarning

        warnings.resetwarnings()
        apply_ultimate_warning_suppression()

        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.devnull:
            self.devnull.close()

        sys.stderr = self.original_stderr
        sys.stdout = self.original_stdout
        warnings.warn = self.original_warn
        warnings.showwarning = self.original_showwarning
        warnings.formatwarning = self.original_formatwarning

        if self.original_filters is not None:
            warnings.filters[:] = self.original_filters

def silence_gemini_warnings(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        with UltimateSuppression():
            return func(*args, **kwargs)
    return wrapper

def silence_gemini_warnings_async(func):
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        with UltimateSuppression():
            return await func(*args, **kwargs)
    return wrapper

